from redbot.core.data_manager import cog_data_path


def get_default_lavalink_settings() -> Dict[str, Any]:
    """Get the default Lavalink server settings."""
    return {
        "server": {
            "address": "localhost",
            "port": 2333,
            "password": "youshallnotpass",
        }
    }


def get_lavalink_config_file() -> pathlib.Path:
    """Get the path to the Lavalink configuration file."""
    return cog_data_path(raw_name="Audio") / "application.yml"


def write_lavalink_config(config: Dict[str, Any]) -> None:
    """Write the Lavalink configuration to the config file."""
    config_file = get_lavalink_config_file()
    with open(config_file, "w") as f:
        yaml.dump(config, f, default_flow_style=False)

